#include <vector>
#include <queue>
#include <tuple>
using namespace std;

class Solution {
    double gain(int p, int t) {
        return (double)(p + 1) / (t + 1) - (double)p / t;
    }

public:
    double maxAverageRatio(vector<vector<int>>& classes, int extraStudents) {
        using T = tuple<double, int, int>;
        priority_queue<T> pq;
        for (const auto& c : classes) {
            pq.push({gain(c[0], c[1]), c[0], c[1]});
        }
        while (extraStudents-- > 0) {
            auto [_, p, t] = pq.top();
            pq.pop();
            p++; t++;
            pq.push({gain(p, t), p, t});
        }
        double sum = 0;
        int n = classes.size();
        while (!pq.empty()) {
            auto [_, p, t] = pq.top();
            pq.pop();
            sum += (double)p / t;
        }
        return sum / n;
    }
};

import java.util.*;

class Solution {
    private double gain(int p, int t) {
        return (double)(p + 1) / (t + 1) - (double)p / t;
    }

    public double maxAverageRatio(int[][] classes, int extraStudents) {
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> Double.compare(gain(b[0], b[1]), gain(a[0], a[1])));
        for (int[] c : classes) {
            pq.offer(new int[]{c[0], c[1]});
        }
        while (extraStudents-- > 0) {
            int[] top = pq.poll();
            top[0]++;
            top[1]++;
            pq.offer(top);
        }
        double sum = 0;
        for (int[] c : pq) {
            sum += (double)c[0] / c[1];
        }
        return sum / classes.length;
    }
}

/**
 * @param {number[][]} classes
 * @param {number} extraStudents
 * @return {number}
 */
var maxAverageRatio = function(classes, extraStudents) {
    const gain = (p, t) => (p + 1) / (t + 1) - p / t;
    const pq = [];

    const push = (item) => {
        pq.push(item);
        let idx = pq.length - 1;
        while (idx > 0) {
            const p = Math.floor((idx - 1) / 2);
            if (pq[p][0] < pq[idx][0]) {
                [pq[p], pq[idx]] = [pq[idx], pq[p]];
                idx = p;
            } else break;
        }
    };

    const pop = () => {
        if (pq.length === 0) return null;
        const top = pq[0];
        const last = pq.pop();
        if (pq.length > 0) {
            pq[0] = last;
            let idx = 0;
            while (true) {
                let left = 2 * idx + 1, right = 2 * idx + 2, largest = idx;
                if (left < pq.length && pq[left][0] > pq[largest][0]) largest = left;
                if (right < pq.length && pq[right][0] > pq[largest][0]) largest = right;
                if (largest !== idx) {
                    [pq[idx], pq[largest]] = [pq[largest], pq[idx]];
                    idx = largest;
                } else break;
            }
        }
        return top;
    };

    for (const [p, t] of classes) {
        push([gain(p, t), p, t]);
    }

    while (extraStudents-- > 0) {
        const [_, p, t] = pop();
        const np = p + 1, nt = t + 1;
        push([gain(np, nt), np, nt]);
    }

    let sum = 0;
    for (const [_, p, t] of pq) {
        sum += p / t;
    }
    return sum / classes.length;
};
